"""Algebraic recovery of the step function for streaming 32-bit hashes.

Model: h_0 = H(b''), and for iterative families try:
  A: h = (h ^ c) * P
  B: h = (h * P) ^ c
  C: h = (h + c) * P
  D: h = rotl(h ^ c, r) * P
  E: h = rotl(h * P + c, r)
  F: h = h * P + c
  G: h = rotl(h, r) ^ c  ... etc.
Recover P from single-byte probes and verify on multi-byte vectors.
"""
import json, sys
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")
M = 0xFFFFFFFF

def rotl(x, r):
    r %= 32
    return ((x << r) | (x >> (32 - r))) & M

def inv32(a):
    return pow(a, -1, 1 << 32)

samples = [json.loads(l) for l in (ROOT / '_work/t1/samples.jsonl').read_text(encoding='utf-8').splitlines()]
H = {}
for s in samples:
    if s['rc'] == 0 and s['out'] and not s['args']:
        parts = s['out'].split()
        H[bytes.fromhex(s['stdin_hex'])] = int(parts[1])

h0 = H[b'']
print('h0 =', h0)
sbyte = {c: H[bytes([c])] for c in range(0x20, 0x7f) if bytes([c]) in H}
print('single-byte probes:', len(sbyte))

# Family A: h(c) = (h0 ^ c) * P  -> P must be consistent
Ps = {}
for c, h in sbyte.items():
    d = (h0 ^ c) & M
    if d & 1:
        Ps.setdefault('A', []).append((h * inv32(d)) & M)
# Family B: h = (h0 * P) ^ c -> h0*P = h ^ c ; P = (h^c) * inv(h0)
if h0 & 1:
    Ps.setdefault('B', []).append(None)
    Ps['B'] = [((h ^ c) * inv32(h0)) & M for c, h in sbyte.items()]
# Family C: h = (h0 + c) * P
Ps.setdefault('C', []).extend(((h * inv32((h0 + c) & M)) & M) for c, h in sbyte.items() if ((h0 + c) & M) & 1)
# Family F: h = h0*P + c -> P = (h - c) * inv(h0)
if h0 & 1:
    Ps.setdefault('F', []).extend((((h - c) * inv32(h0)) & M) for c, h in sbyte.items())
# Family D/E: rot variants
for r in range(1, 32):
    # D: h = rotl(h0 ^ c, r) * P
    cand = []
    for c, h in sbyte.items():
        d = rotl(h0 ^ c, r)
        if d & 1:
            cand.append((h * inv32(d)) & M)
    if len(set(cand)) == 1 and cand:
        print(f'family D r={r}: P={cand[0]:#010x} UNIQUE')
    # E: h = rotl(h0 * P + c, r) -> h0*P + c = rotr(h, r) -> P = (rotr(h,r) - c)*inv(h0)
    if h0 & 1:
        cand2 = [((( (M >> (32-r)) | (h << (32-r)) if False else ((h >> r) | (h << (32-r))) & M ) - c) * inv32(h0)) & M for c, h in sbyte.items()]
        if len(set(cand2)) == 1 and cand2:
            print(f'family E r={r}: P={cand2[0]:#010x} UNIQUE')

for fam, lst in Ps.items():
    uniq = set(lst)
    print(f'family {fam}: {len(uniq)} distinct candidates', [hex(x) for x in list(uniq)[:5]] if len(uniq) <= 5 else 'too many')

# If any single-P candidate found, verify on multi-byte vectors
def try_stream(step):
    bad = 0
    for b, h in H.items():
        x = h0
        for byte in b:
            x = step(x, byte)
        if x != h:
            bad += 1
    return bad

multi = [(b, h) for b, h in H.items() if len(b) > 1]
for fam, lst in Ps.items():
    for P in list(set(lst))[:20]:
        if fam == 'A':
            step = lambda x, c, P=P: ((x ^ c) * P) & M
        elif fam == 'B':
            step = lambda x, c, P=P: ((x * P) & M) ^ c
        elif fam == 'C':
            step = lambda x, c, P=P: (((x + c) & M) * P) & M
        elif fam == 'F':
            step = lambda x, c, P=P: ((x * P) + c) & M
        else:
            continue
        bad = try_stream(step)
        if bad == 0:
            print(f'STREAM MATCH family {fam} P={P:#x} on {len(multi)} multi-byte vectors!')
